#requires -Version 5.1
<#
.SYNOPSIS
    Deterministically reconstructs and repairs the Mayhem repository from the audited source dump.
.DESCRIPTION
    Generated from the completed Mayhem repository TXT dump.
    The script never reads, writes, copies, or backs up the real .env file.
#>
param(
    [Parameter(Position = 0)]
    [string]$Root = (Get-Location).Path
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

$Root = [System.IO.Path]::GetFullPath($Root)

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " MAYHEM REBUILD + AUDIT FIXES" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "Target: $Root" -ForegroundColor DarkGray
Write-Host ""

if (-not (Test-Path -LiteralPath $Root -PathType Container)) {
    Write-Host "Creating repository root: $Root" -ForegroundColor Yellow
    New-Item -ItemType Directory -Path $Root -Force | Out-Null
}

$existingPackage = Join-Path $Root "package.json"
if (Test-Path -LiteralPath $existingPackage -PathType Leaf) {
    try {
        $packageProbe = Get-Content -LiteralPath $existingPackage -Raw -Encoding UTF8 | ConvertFrom-Json
    } catch {
        throw "Existing package.json is not valid JSON: $existingPackage"
    }
    if ($packageProbe.name -and $packageProbe.name -ne "mayhem") {
        throw "Target root contains a different package.json project ($($packageProbe.name)). Use a fresh Mayhem root or specify the correct root."
    }
}

$backupStamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path (Split-Path -Parent $Root) ("mayhem-rebuild-backup-" + $backupStamp)
$backupCreated = $false
$operations = [System.Collections.Generic.List[string]]::new()

function Ensure-Directory {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Container)) {
        New-Item -ItemType Directory -Path $Path -Force | Out-Null
        Write-Host "CREATE DIR  $Path" -ForegroundColor DarkCyan
        $script:operations.Add("CREATE DIR $Path")
    }
}

function Backup-ExistingFile {
    param([Parameter(Mandatory)][string]$Path)
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
    if ([System.IO.Path]::GetFileName($Path) -eq ".env") {
        throw "Safety violation: attempted to back up .env. This script never touches real environment secrets."
    }
    $relative = $Path.Substring($Root.Length).TrimStart("\","/")
    $destination = Join-Path $backupRoot $relative
    Ensure-Directory (Split-Path -Parent $destination)
    Copy-Item -LiteralPath $Path -Destination $destination -Force
    $script:backupCreated = $true
    Write-Host "BACKUP      $relative -> $destination" -ForegroundColor DarkYellow
    $script:operations.Add("BACKUP $relative")
}

function Write-Utf8File {
    param(
        [Parameter(Mandatory)][string]$RelativePath,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Content
    )

    if ($RelativePath -eq ".env") {
        throw "Safety violation: generated rebuild attempted to write .env."
    }

    $path = Join-Path $Root $RelativePath
    Ensure-Directory (Split-Path -Parent $path)

    $existing = $null
    if (Test-Path -LiteralPath $path -PathType Leaf) {
        $existing = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    }

    if ($null -ne $existing -and $existing -ceq $Content) {
        Write-Host "UNCHANGED   $RelativePath" -ForegroundColor DarkGray
        $script:operations.Add("UNCHANGED $RelativePath")
        return
    }

    Backup-ExistingFile $path
    $utf8 = New-Object System.Text.UTF8Encoding($false)
    [System.IO.File]::WriteAllText($path, $Content, $utf8)

    if ($null -eq $existing) {
        Write-Host "CREATE      $RelativePath" -ForegroundColor Green
        $script:operations.Add("CREATE $RelativePath")
    } else {
        Write-Host "REPLACE     $RelativePath" -ForegroundColor Green
        $script:operations.Add("REPLACE $RelativePath")
    }
}

function Move-ObsoleteItem {
    param([Parameter(Mandatory)][string]$RelativePath)
    $path = Join-Path $Root $RelativePath
    if (-not (Test-Path -LiteralPath $path)) {
        return
    }
    if ($RelativePath -eq ".env" -or $RelativePath -like "*.env") {
        throw "Safety violation: attempted to move a real environment file."
    }
    $destination = Join-Path $backupRoot $RelativePath
    Ensure-Directory (Split-Path -Parent $destination)
    Copy-Item -LiteralPath $path -Destination $destination -Recurse -Force
    $script:backupCreated = $true
    Remove-Item -LiteralPath $path -Recurse -Force
    Write-Host "REMOVE      $RelativePath (backup: $destination)" -ForegroundColor Magenta
    $script:operations.Add("REMOVE $RelativePath")
}

Write-Host "[1/4] Preserving real environment secrets..." -ForegroundColor Yellow
if (Test-Path -LiteralPath (Join-Path $Root ".env") -PathType Leaf) {
    Write-Host "PRESERVE    .env (not read, copied, modified, or deleted)" -ForegroundColor Green
    $operations.Add("PRESERVE .env")
}

Write-Host "[2/4] Removing only repository artifacts proven stale or obsolete..." -ForegroundColor Yellow
Move-ObsoleteItem '.prettierrc.json'
Move-ObsoleteItem '.eslintrc.json'
Move-ObsoleteItem 'anarchbot 1.code-workspace'
Move-ObsoleteItem 'apply_mayhem_audit_fixes.ps1'
Move-ObsoleteItem 'rebuild-mayhem-dashboard.ps1'
Move-ObsoleteItem 'tsconfig.base.mayhem-bot.json'
Move-ObsoleteItem 'turbo.json'
Move-ObsoleteItem 'MAYHEM_FULL_SOURCE_AUDIT.txt'
Move-ObsoleteItem 'MAYHEM_FULL_SOURCE_AUDIT_SAFE.txt'
Move-ObsoleteItem 'infrastructure\docker\Dockerfile.txt'
Move-ObsoleteItem 'dashboard-backup-20260810-220054'
Move-ObsoleteItem 'packages\core-types\src\schema.ts'

Write-Host "[3/4] Writing reconstructed repository..." -ForegroundColor Yellow
Write-Utf8File '.agent.md' @'
# MAYHEM ROOT ORGANIZER

## Purpose
Organize the Mayhem repository root into a clean, production-oriented monorepo structure without changing trading behavior, execution logic, risk semantics, security controls, or business logic.

## When to use
- When the task is to inventory, classify, and reorganize repository root files and directories.
- When you need to separate packages, services, apps, documentation, scripts, infrastructure, and tests.
- When you are preserving existing audit, risk, and ledger code while making the repository easier to maintain.

## What this agent does
- Inspects the current root tree and package boundaries.
- Classifies each root item as CORE, PACKAGE, SERVICE, APPLICATION, AGENT, TEST, SCRIPT, INFRASTRUCTURE, DOCUMENTATION, CONFIGURATION, CI/CD, GENERATED, TEMPORARY, LEGACY, or UNKNOWN.
- Creates a safe move plan for unambiguous root cleanup.
- Identifies stale references such as `mayhem-bot` and broken CI paths.
- Preserves all critical components: risk engine, ledger, security docs, package manifests, TypeScript config, CI workflows, tests, and agent manifests.

## What this agent does not do
- Do not connect wallets, expose private keys, or add credentials.
- Do not execute trades, broadcast Solana transactions, or implement sniper/MEV behavior.
- Do not bypass risk controls or weaken security gates.
- Do not delete audit/security documentation or remove tests.
- Do not create fake production accounting, market-data ingestion, or execution implementations.

## Tool guidance
- Prefer using repository inspection and file management tools to gather structure, search references, and update paths.
- Avoid any tool or action that creates live network traffic, handles secrets, or alters production-sensitive behavior.
- Do not move files unless the classification is unambiguous and the source-of-truth repository contents support it.

## Example prompts
- "Inventory the current Mayhem root structure and propose a safe organization plan."
- "Classify root files into service, package, app, infrastructure, and documentation categories."
- "Find stale `mayhem-bot` references and broken CI paths without altering code yet."
- "Create a move plan that preserves risk engine, ledger, and audit artifacts."

## Related customizations to create next
- A dedicated `mayhem-ci-maintainer.agent.md` for CI workflow cleanup and validation.
- A `mayhem-agent-boundary.agent.md` for enforcing agent/risk/execution separation.
- A `mayhem-docs-organizer.agent.md` for documentation reclassification and audit reporting.
'@
