Write-Utf8File 'apps\api\src\index.ts' @'
import dotenv from 'dotenv';
import path from 'node:path';
import fs from 'node:fs';
import express from 'express';
import cors from 'cors';
import helmet from 'helmet';
import { createRoutes } from './routes';
import { BotState } from './state';

function findEnvFile(): string {
  let dir = process.cwd();
  for (let i = 0; i < 5; i++) {
    const candidate = path.join(dir, '.env');
    if (fs.existsSync(candidate)) return candidate;
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return path.resolve(process.cwd(), '.env');
}

dotenv.config({ path: findEnvFile(), override: false });

const app = express();
app.disable('x-powered-by');
app.use(helmet());

const corsOrigins = (process.env.CORS_ORIGINS ?? '')
  .split(',')
  .map((origin) => origin.trim())
  .filter(Boolean);

app.use(
  cors(
    corsOrigins.length > 0
      ? { origin: corsOrigins }
      : process.env.NODE_ENV === 'production'
        ? { origin: false }
        : undefined,
  ),
);
app.use(express.json());

const state = new BotState();
state.dryRun = process.env.DRY_RUN?.toLowerCase() !== 'false';
const requestedTradingEnabled =
  process.env.TRADING_ENABLED?.toLowerCase() === 'true';
state.tradingEnabled = requestedTradingEnabled && !state.dryRun;
state.status = state.dryRun ? 'DRY_RUN' : 'RUNNING';
state.startedAt = new Date();

const configuredTokens = [
  process.env.API_AUTH_TOKEN,
  ...(process.env.API_KEYS ?? '')
    .split(',')
    .map((value) => value.trim())
    .filter(Boolean),
].filter((value): value is string => Boolean(value));

const authMiddleware = (
  req: express.Request,
  res: express.Response,
  next: express.NextFunction,
) => {
  const production = process.env.NODE_ENV === 'production';

  if (configuredTokens.length === 0) {
    if (production) {
      res.status(503).json({ error: 'API authentication is not configured' });
      return;
    }

    next();
    return;
  }

  const provided = req.headers.authorization?.startsWith('Bearer ')
    ? req.headers.authorization.slice('Bearer '.length)
    : undefined;

  if (!provided || !configuredTokens.includes(provided)) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  next();
};

app.get('/health', (_req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

const routes = createRoutes(state);

app.get('/api/status', routes.getStatus);
app.get('/api/tokens', routes.getTokens);
app.get('/api/launches', routes.getLaunches);
app.get('/api/positions', routes.getPositions);
app.get('/api/trades', routes.getTrades);
app.get('/api/balance', routes.getBalance);
app.get('/api/config', routes.getConfig);
app.get('/api/telemetry', routes.getTelemetry);

app.post('/api/start', authMiddleware, routes.start);
app.post('/api/pause', authMiddleware, routes.pause);
app.post('/api/emergency-stop', authMiddleware, routes.emergencyStop);
app.post('/api/positions/:id/close', authMiddleware, routes.closePosition);

const host = process.env.API_HOST || '0.0.0.0';
const port = parseInt(process.env.API_PORT || '3001', 10);
const server = app.listen(port, host, () => {
  console.log(JSON.stringify({ level: 'info', msg: `API listening on ${host}:${port}`, timestamp: new Date().toISOString() }));
});

const shutdown = (signal: string) => {
  server.close((error) => {
    if (error) {
      console.error(JSON.stringify({ level: 'error', msg: `Failed to shut down cleanly: ${error.message}`, signal, timestamp: new Date().toISOString() }));
      process.exitCode = 1;
      return;
    }
    console.log(JSON.stringify({ level: 'info', msg: `API shut down (${signal})`, timestamp: new Date().toISOString() }));
  });
};

process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));

export default app;
