import { RiskEngine } from '@mayhem/risk-engine';
import { isPumpFunToken } from '@mayhem/execution';
import { TokenRiskGate } from './new-launch-handler';

export class RiskGateAdapter implements TokenRiskGate {
  constructor(private riskEngine: RiskEngine) {}

  async assess(input: {
    tokenMint: string;
    poolAddress?: string;
    source: string;
    initialLiquidity: number;
    quote: { price: number; timestamp: number; priceImpactBps: number };
    isPumpFun: boolean;
  }) {
    const liqCheck = this.riskEngine.checkLiquidity(input.initialLiquidity);

    if (input.isPumpFun) {
      return {
        score: 90,
        level: 'SAFE' as const,
        canTrade: true,
        reason: 'pump.fun token — bonding curve',
      };
    }

    if (!liqCheck.passed) {
      return {
        score: 10,
        level: 'BLOCKED' as const,
        canTrade: false,
        reason: liqCheck.message,
      };
    }

    return {
      score: 90,
      level: 'SAFE' as const,
      canTrade: true,
      reason: 'basic checks passed',
    };
  }
}
