function formatPrice(value: number): string {
  if (value >= 1) return `$${value.toFixed(2)}`;
  if (value >= 0.01) return `$${value.toFixed(4)}`;
  if (value >= 0.000001) return `$${value.toFixed(7)}`;
  return `$${value.toExponential(2)}`;
}

function formatCompact(value: number): string {
  if (value >= 1_000_000) {
    return `$${(value / 1_000_000).toFixed(2)}M`;
  }

  if (value >= 1_000) {
    return `$${(value / 1_000).toFixed(1)}K`;
  }

  return `$${value.toFixed(0)}`;
}

function ageLabel(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
  return `${Math.floor(seconds / 3600)}h`;
}

function App() {
  const [tokens, setTokens] = useState<MarketToken[]>(INITIAL_TOKENS);
  const [selectedId, setSelectedId] = useState<string>(INITIAL_TOKENS[0]?.id || '');
  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState<'ALL' | 'NEW' | 'TRENDING' | 'WATCHLIST'>(
    'ALL',
  );
  const [side, setSide] = useState<OrderSide>('BUY');
  const [amount, setAmount] = useState('0.10');
  const [slippage, setSlippage] = useState('1.0');
  const [botRunning, setBotRunning] = useState(false);
  const [walletConnected, setWalletConnected] = useState(false);
  const [activity, setActivity] = useState<string[]>([
    'MAYHEM TERMINAL initialized',
    'Market scanner online',
    'Risk engine ready',
    'Waiting for execution commands',
  ]);

  const selected = useMemo<MarketToken>(
    () => tokens.find((token) => token.id === selectedId) ?? tokens[0] ?? INITIAL_TOKENS[0]!,
    [tokens, selectedId],
  );

  const filteredTokens = useMemo(() => {
    const query = search.trim().toLowerCase();

    return tokens.filter((token) => {
      const matchesSearch =
        query.length === 0 ||
        token.symbol.toLowerCase().includes(query) ||
        token.name.toLowerCase().includes(query) ||
        token.address.toLowerCase().includes(query);

      if (!matchesSearch) return false;

      if (filter === 'NEW') return token.ageSec < 600;
      if (filter === 'TRENDING') return token.change5m > 15;
      if (filter === 'WATCHLIST') {
        return token.symbol === 'MAYHEM' || token.symbol === 'OPTIK';
      }

      return true;
    });
  }, [tokens, search, filter]);

  const addActivity = (message: string) => {
    setActivity((current) => [
      `${new Date().toLocaleTimeString()} — ${message}`,
      ...current,
    ].slice(0, 8));
  };

  const executeOrder = () => {
    const numericAmount = Number(amount);

    if (!Number.isFinite(numericAmount) || numericAmount <= 0) {
      addActivity('ORDER REJECTED — invalid amount');
      return;
    }

    addActivity(
      `${side} ${numericAmount.toFixed(3)} SOL ${selected.symbol} — DEMO ORDER`,
    );
  };

  const toggleBot = () => {
    const next = !botRunning;
    setBotRunning(next);
    addActivity(next ? 'MAYHEM BOT STARTED — DEMO MODE' : 'MAYHEM BOT STOPPED');
  };

  const simulateMarketUpdate = () => {
    setTokens((current) =>
      current.map((token) => {
        const movement = (Math.random() - 0.45) * 0.018;
        const nextPrice = Math.max(token.price * (1 + movement), 0.00000001);

        return {
          ...token,
          price: nextPrice,
          change1m: token.change1m + movement * 100,
          volume24h: token.volume24h + Math.random() * 1500,
        };
      }),
    );

    addActivity('Market data refreshed');
  };

  return (
    <div className="mayhem-terminal">
      <header className="terminal-header">
        <div className="brand">
          <div className="brand-mark">M</div>

