import {  useMemo  } from 'react';
import type { MarketToken } from '../../types/terminal';

interface Props {
  token: MarketToken;
}

export function PriceChart({ token }: Props) {
  const points = useMemo(() => {
    const result: number[] = [];
    let value = token.price * 0.74;

    for (let i = 0; i < 80; i++) {
      value *= 1 + ((Math.sin(i * 0.7) * 0.012) + 0.008);
      result.push(value);
    }

    result[result.length - 1] = token.price;
    return result;
  }, [token]);

  const min = Math.min(...points);
  const max = Math.max(...points);
  const width = 760;
  const height = 280;

  const path = points
    .map((value, index) => {
      const x = (index / (points.length - 1)) * width;
      const y = height - ((value - min) / (max - min || 1)) * height;
      return `${index === 0 ? 'M' : 'L'} ${x.toFixed(2)} ${y.toFixed(2)}`;
    })
    .join(' ');

  return (
    <section className="chart-panel">
      <div className="chart-header">
        <div>
          <div className="chart-symbol">
            {token.symbol}/SOL
          </div>
          <div className="chart-price">
            ${token.price.toFixed(8)}
          </div>
        </div>

        <div className="chart-change positive">
          +{token.change15m.toFixed(2)}%
        </div>

        <div className="chart-intervals">
          {['1m', '5m', '15m', '1h'].map(interval => (
            <button
              className={interval === '1m' ? 'active' : ''}
              key={interval}
            >
              {interval}
            </button>
          ))}
        </div>
      </div>

      <div className="chart-wrap">
        <svg
          viewBox={`0 0 ${width} ${height}`}
          preserveAspectRatio="none"
          className="price-svg"
        >
          <defs>
            <linearGradient id="mayhemGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="rgba(34,197,94,.25)" />
              <stop offset="100%" stopColor="rgba(34,197,94,0)" />
            </linearGradient>
          </defs>

          <path
            d={`${path} L ${width} ${height} L 0 ${height} Z`}
            fill="url(#mayhemGradient)"
          />

          <path
            d={path}
            fill="none"
            stroke="#22c55e"
            strokeWidth="2"
          />
        </svg>
      </div>
    </section>
  );
}
