import type { MarketToken } from '../../types/terminal';

interface Props {
  tokens: MarketToken[];
  selected: MarketToken;
  onSelect: (token: MarketToken) => void;
  search: string;
  onSearch: (value: string) => void;
}

function money(value: number) {
  if (value >= 1_000_000) return `$${(value / 1_000_000).toFixed(2)}M`;
  if (value >= 1_000) return `$${(value / 1_000).toFixed(1)}K`;
  return `$${value.toFixed(0)}`;
}

function age(seconds: number) {
  if (seconds < 60) return `${seconds}s`;
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m`;
  return `${Math.floor(seconds / 3600)}h`;
}

export function TokenTable({
  tokens,
  selected,
  onSelect,
  search,
  onSearch,
}: Props) {
  return (
    <section className="token-market">
      <div className="market-toolbar">
        <div>
          <span className="section-title">LIVE TOKENS</span>
          <span className="live-dot" />
        </div>

        <input
          className="search-input"
          value={search}
          onChange={event => onSearch(event.target.value)}
          placeholder="Search token..."
        />
      </div>

      <div className="token-table-head">
        <span>TOKEN</span>
        <span>PRICE</span>
        <span>5M</span>
        <span>LIQ</span>
        <span>MCAP</span>
        <span>AGE</span>
      </div>

      <div className="token-list">
        {tokens.map(token => (
          <button
            key={token.id}
            className={`token-row ${
              selected.id === token.id ? 'selected' : ''
            }`}
            onClick={() => onSelect(token)}
          >
            <span className="token-name">
              <strong>{token.symbol}</strong>
              <small>{token.name}</small>
            </span>

            <span>${token.price.toFixed(7)}</span>

            <span className={token.change5m >= 0 ? 'positive' : 'negative'}>
              {token.change5m >= 0 ? '+' : ''}
              {token.change5m.toFixed(1)}%
            </span>

            <span>{money(token.liquidity)}</span>
            <span>{money(token.marketCap)}</span>
            <span>{age(token.ageSec)}</span>
          </button>
        ))}
      </div>
    </section>
  );
}
