import {  useState  } from 'react';
import type { MarketToken, TradeSide } from '../../types/terminal';

interface Props {
  token: MarketToken;
  onActivity: (detail: string, severity?: 'info' | 'success' | 'warning' | 'error') => void;
}

export function TradePanel({ token, onActivity }: Props) {
  const [side, setSide] = useState<TradeSide>('BUY');
  const [amount, setAmount] = useState('0.10');
  const [slippage, setSlippage] = useState('1');

  function execute() {
    const action = side === 'BUY' ? 'BUY' : 'SELL';

    onActivity(
      `DEMO ${action} submitted for ${token.symbol}: ${amount} SOL`,
      'success',
    );
  }

  return (
    <section className="trade-panel">
      <div className="trade-tabs">
        <button
          className={side === 'BUY' ? 'buy active' : ''}
          onClick={() => setSide('BUY')}
        >
          BUY
        </button>

        <button
          className={side === 'SELL' ? 'sell active' : ''}
          onClick={() => setSide('SELL')}
        >
          SELL
        </button>
      </div>

      <div className="trade-token">
        <div className="token-avatar">
          {token.symbol.slice(0, 1)}
        </div>

        <div>
          <strong>{token.symbol}</strong>
          <small>{token.address}</small>
        </div>
      </div>

      <label>AMOUNT · SOL</label>

      <input
        className="trade-input"
        value={amount}
        onChange={event => setAmount(event.target.value)}
        inputMode="decimal"
      />

      <div className="quick-buttons">
        {['0.05', '0.10', '0.25', '0.50', '1.00'].map(value => (
          <button key={value} onClick={() => setAmount(value)}>
            {value}
          </button>
        ))}
      </div>

      <label>SLIPPAGE</label>

      <div className="slippage-row">
        {['0.5', '1', '2', '5'].map(value => (
          <button
            key={value}
            className={slippage === value ? 'active' : ''}
            onClick={() => setSlippage(value)}
          >
            {value}%
          </button>
        ))}
      </div>

      <div className="trade-details">
        <div>
          <span>Priority fee</span>
          <strong>0.0002 SOL</strong>
        </div>

        <div>
          <span>Max fee</span>
          <strong>0.0010 SOL</strong>
        </div>

        <div>
          <span>MEV protection</span>
          <strong className="positive">ON</strong>
        </div>
      </div>

      <button
        className={`execute-button ${side.toLowerCase()}`}
        onClick={execute}
      >
        {side === 'BUY' ? 'EXECUTE BUY' : 'EXECUTE SELL'}
      </button>

      <div className="demo-notice">
        DEMO MODE · No transaction will be submitted
      </div>
    </section>
  );
}
