  },
  {
    id: '2',
    symbol: 'ANARCHY',
    name: 'Anarchy',
    address: 'Anar...4Pq9',
    price: 0.0000842,
    marketCap: 84200,
    liquidity: 39800,
    volume24h: 312000,
    change1m: 12.8,
    change5m: 24.2,
    change15m: 37.5,
