    risk: 41,
    graduated: false,
    watchlisted: false,
  },
  {
    id: '3',
    symbol: 'QUANT',
    name: 'Quantum Dog',
    address: 'Quan...9Tx1',
    price: 0.000912,
    marketCap: 912000,
    liquidity: 184000,
    volume24h: 920000,
    change1m: 7.2,
    change5m: 18.4,
    change15m: 21.9,
    holders: 4210,
    ageSec: 1840,
    risk: 22,
    graduated: true,
    watchlisted: true,
  },
  {
    id: '4',
    symbol: 'VOID',
    name: 'Void Protocol',
    address: 'Void...3Lm7',
    price: 0.0000341,
    marketCap: 34100,
    liquidity: 9200,
    volume24h: 88000,
    change1m: -4.1,
    change5m: 2.8,
    change15m: 9.4,
    holders: 288,
    ageSec: 74,
    risk: 72,
    graduated: false,
    watchlisted: false,
  },
  {
    id: '5',
    symbol: 'ROCKET',
    name: 'Rocket Fuel',
    address: 'Rock...2Va8',
    price: 0.00142,
    marketCap: 1420000,
    liquidity: 292000,
    volume24h: 2100000,
    change1m: 4.8,
    change5m: 11.2,
    change15m: 15.4,
    holders: 8120,
    ageSec: 4200,
    risk: 17,
    graduated: true,
    watchlisted: false,
  },
];

export function useMarket() {
  const [filter, setFilter] = useState('ALL');
  const [search, setSearch] = useState('');

  const tokens = useMemo(() => {
    let result = TOKENS;

    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(
        token =>
          token.symbol.toLowerCase().includes(q) ||
          token.name.toLowerCase().includes(q),
      );
    }

    switch (filter) {
      case 'NEW':
        result = result.filter(token => token.ageSec < 600);
        break;
      case 'TRENDING':
        result = result.filter(token => token.change5m > 15);
        break;
      case 'VOLUME':
        result = [...result].sort((a, b) => b.volume24h - a.volume24h);
        break;
      case 'LIQUIDITY':
        result = [...result].sort((a, b) => b.liquidity - a.liquidity);
        break;
      case 'RISK':
        result = [...result].sort((a, b) => a.risk - b.risk);
        break;
      case 'WATCHLIST':
        result = result.filter(token => token.watchlisted);
        break;
      case 'GRADUATED':
        result = result.filter(token => token.graduated);
        break;
      default:
        break;
    }

    return result;
  }, [filter, search]);

  return {
    tokens,
    filter,
    setFilter,
    search,
    setSearch,
  };
}
