{
  "name": "@mayhem/agent-sdk",
  "version": "0.1.0",
  "private": true,
  "description": "Agent runtime SDK and orchestration primitives.",
  "license": "UNLICENSED",
  "type": "commonjs",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
    ,"./*": "./src/*.ts"
  },
  "files": ["dist"],
  "scripts": {
    "build": "tsc --build tsconfig.build.json",
    "clean": "tsc --build tsconfig.build.json --clean"
  },
  "dependencies": {
    "@mayhem/core-types": "workspace:*"
  }
}
'@
Write-Utf8File 'packages\agent-sdk\src\index.ts' @'

export interface AgentContext<T = Record<string, unknown>> {
  id: string;
  name: string;
  metadata: T;
  createdAt: string;
}

export interface AgentTask<T = Record<string, unknown>> {
  id: string;
  name: string;
  payload: T;
  createdAt: string;
}

export function createAgentContext<T>(name: string, metadata: T): AgentContext<T> {
  return {
    id: `agent-${Math.random().toString(36).slice(2, 10)}`,
    name,
    metadata,
    createdAt: new Date().toISOString(),
  };
}

export function createAgentTask<T>(name: string, payload: T): AgentTask<T> {
  return {
    id: `task-${Math.random().toString(36).slice(2, 10)}`,
    name,
    payload,
    createdAt: new Date().toISOString(),
  };
}
'@
Write-Utf8File 'packages\agent-sdk\tsconfig.build.json' @'

{
  "extends": "../../tsconfig.base.json",
  "compilerOptions": {
    "rootDir": "./src",
    "outDir": "./dist"
  },
  "include": ["src/**/*.ts"],
  "exclude": ["src/**/*.test.ts"],
  "references": [{ "path": "../core-types/tsconfig.build.json" }]
}
'@
Write-Utf8File 'packages\agent-sdk\tsconfig.build.tsbuildinfo' @'

