import { Connection, Keypair, PublicKey } from "@solana/web3.js";
import { JitoClient } from "./jito";
import { FeeBudget } from "./fee-budget";
import {
  buildSnipeTx, estimateTokensOut, globalPda,
  parseGlobal, PUMP_FEE_BPS, readBondingCurve,
} from "./pumpfun";
import { CircuitBreaker, GateResult } from "@mayhem/risk-engine";
import type { LaunchSignal } from "@mayhem/token-monitor";

export interface EngineConfig {
  hotWallet: Keypair;
  positionSolLamports: bigint;
  maxSlippagePct: number;
  maxConcurrentPositions: number;
  maxTxAgeMs: number;      // skip launches older than this
  landingTimeoutMs: number; // timeout for waiting on bundle landing
  preflightSim: boolean;   // require simulator pass before send
}

export type SnipeResult =
  | { status: "landed"; bundleId: string; mint: PublicKey }
  | { status: "blocked" | "skipped" | "failed"; reason: string; mint: PublicKey };

export class SnipeEngine {
  private readonly orders = new Map<string, number>(); // mint base58 -> placedAt (idempotency)
  private feeRecipient: PublicKey | null = null;

  private evictStale(now = Date.now(), ttlMs = 600_000): void {
    for (const [mint, at] of this.orders) {
      if (now - at > ttlMs) this.orders.delete(mint);
    }
  }

  constructor(
    private readonly conn: Connection,
    private readonly jito: JitoClient,
    private readonly fees: FeeBudget,
    private readonly breaker: CircuitBreaker,
    private readonly cfg: EngineConfig,
  ) {}

  async snipe(
    signal: LaunchSignal & { mint: PublicKey },
    simulate: (mint: PublicKey, sizeLamports: bigint) => Promise<{ ok: boolean; reason?: string }>,
  ): Promise<SnipeResult> {
    const { mint } = signal;
    const mintKey = mint.toBase58();
    this.evictStale();

    // 1. Circuit breaker — HARD gate, checked before anything else
    const gate: GateResult = this.breaker.shouldBlock();
    if (gate.block) return { status: "blocked", reason: gate.reason ?? "breaker", mint };

    // 2. Idempotency + concurrency caps
    if (this.orders.has(mintKey)) return { status: "skipped", reason: "duplicate", mint };
    if (this.orders.size >= this.cfg.maxConcurrentPositions) return { status: "skipped", reason: "max_concurrent", mint };

    // 3. Freshness — a 6-second-old launch is a bag, not an edge
    if (Date.now() - signal.detectedAt > this.cfg.maxTxAgeMs) return { status: "skipped", reason: "stale", mint };

    // 4. Preflight simulation — mandatory when enabled
    if (this.cfg.preflightSim) {
      const sim = await simulate(mint, this.cfg.positionSolLamports);
      if (!sim.ok) return { status: "skipped", reason: sim.reason ?? "sim_failed", mint };
    }

    // 5. Curve state: live bonding curve, fall back to global initial reserves at launch block
    const global = await this.loadGlobal();
    const state = (await readBondingCurve(this.conn, mint)) ?? global;
    const feeRecipient = this.feeRecipient;
    if (!feeRecipient) throw new Error("pump.fun fee recipient not loaded");

    // 6. Slippage cap = position + pump fee (1%) + allowed slippage
    const feeBps = BigInt(PUMP_FEE_BPS);
    const slipBps = BigInt(Math.round(this.cfg.maxSlippagePct * 100)); // 30% → 3000
    const maxSolCost =
      (this.cfg.positionSolLamports * (10_000n + feeBps + slipBps)) / 10_000n;
    const tokenAmount = estimateTokensOut(state, this.cfg.positionSolLamports);

    // 8. Build, sign, bundle, send
    const { blockhash } = await this.conn.getLatestBlockhash("confirmed");
    const buyTx = await buildSnipeTx(this.conn, {
      mint,
      payer: this.cfg.hotWallet.publicKey,
      feeRecipient,
      tokenAmount,
      maxSolCostLamports: maxSolCost,
      blockhash,
    });
    buyTx.sign(this.cfg.hotWallet);

    const tip = await this.fees.tipLamports();
    const tipTx = await this.jito.buildTipTx(this.cfg.hotWallet, blockhash, tip);

    const gate2 = this.breaker.shouldBlock();
    if (gate2.block) return { status: "blocked", reason: gate2.reason ?? "breaker", mint };

  // step 8 (build/send) — fix the terminal states:
    this.orders.set(mintKey, Date.now());
    const bundleId = await this.jito.sendBundle([tipTx, buyTx]);
    const landed = await this.jito.waitForLanding(bundleId, this.cfg.landingTimeoutMs);

    if (landed.status !== "Landed") {
      this.orders.delete(mintKey);                       // failed → free the slot
      return { status: "failed", reason: `bundle_${landed.status}`, mint };
    }
    this.orders.delete(mintKey);                          // landed → slot freed; position-manager owns the open position
    return { status: "landed", bundleId, mint };  
     }

  private async loadGlobal(): Promise<{ virtualTokenReserves: bigint; virtualSolReserves: bigint }> {
    const data = (await this.conn.getAccountInfo(globalPda()))?.data as Buffer | undefined;
    if (!data) throw new Error("pump.fun global account not found");
    const global = parseGlobal(data);
    this.feeRecipient ??= global.feeRecipient;
    return {
      virtualTokenReserves: global.virtualTokenReserves,
      virtualSolReserves: global.virtualSolReserves,
    };
  }
}
'@
Write-Utf8File 'packages\execution\src\fee-budget.ts' @'

export type TipPercentile = 25 | 50 | 75 | 95 | 99;

export interface TipFloorRow {
  time: string;
  landed_tips_25th_percentile: number;
  landed_tips_50th_percentile: number;
  landed_tips_75th_percentile: number;
  landed_tips_95th_percentile: number;
  landed_tips_99th_percentile: number;
  ema_landed_tips_50th_percentile: number;
}

export interface FeeBudgetConfig {
  strategy: "percentile" | "fixed";
  percentile?: TipPercentile;      // default 50
  fixedLamports?: number;
  maxTipLamports: number;          // HARD CAP — tips must never eat the edge
  tipFloorUrl?: string;            // default https://bundles.jito.wtf/api/v1/bundles/tip_floor
  cacheMs?: number;                // default 30_000
}

export class FeeBudget {
  private last: { row: TipFloorRow; at: number } | null = null;

  constructor(private readonly cfg: FeeBudgetConfig) {}

  async tipLamports(): Promise<number> {
    let lamports: number;
    if (this.cfg.strategy === "fixed") {
      lamports = this.cfg.fixedLamports ?? 0;
    } else {
      const row = await this.floor();
      const pct = this.cfg.percentile ?? 50;
      lamports = Math.ceil(row[`landed_tips_${pct}th_percentile`] * 1_000_000_000);
    }
    return Math.max(0, Math.min(lamports, this.cfg.maxTipLamports));
  }

  private async floor(): Promise<TipFloorRow> {
    const now = Date.now();
    const cacheMs = this.cfg.cacheMs ?? 30_000;
    if (this.last && now - this.last.at < cacheMs) return this.last.row;
    const url = this.cfg.tipFloorUrl ?? "https://bundles.jito.wtf/api/v1/bundles/tip_floor";
    const res = await fetch(url, { signal: AbortSignal.timeout(2_000) });
    if (!res.ok) throw new Error(`tip_floor: HTTP ${res.status}`);
    const rows = (await res.json()) as TipFloorRow[];
    if (rows.length === 0) {
      throw new Error("tip_floor: no data returned");
    }
    const row = rows[rows.length - 1]; // newest entry
    if (!row) {
      throw new Error("tip_floor: no data returned");
    }
    this.last = { row, at: now };
    return row;
  }
}
