{
  "name": "@mayhem/market-data",
  "version": "0.1.0",
  "private": true,
  "description": "Market data adapters and normalization for Solana feeds.",
  "license": "UNLICENSED",
  "type": "commonjs",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
    ,"./*": "./src/*.ts"
  },
  "files": ["dist"],
  "scripts": {
    "build": "tsc --build tsconfig.build.json",
    "clean": "tsc --build tsconfig.build.json --clean"
  },
  "dependencies": {
    "@mayhem/core-types": "workspace:*"
  }
}
'@
Write-Utf8File 'packages\market-data\src\index.ts' @'

export interface MarketSnapshot {
  symbol: string;
  price: number;
  source: string;
  timestamp: string;
}

export interface MarketDataAdapter {
  getSnapshot(symbol: string): Promise<MarketSnapshot>;
}

export class MarketDataClient implements MarketDataAdapter {
  constructor(private readonly source = 'default') {}

  async getSnapshot(symbol: string): Promise<MarketSnapshot> {
    return {
      symbol,
      price: 0,
      source: this.source,
      timestamp: new Date().toISOString(),
    };
  }
}
'@
Write-Utf8File 'packages\market-data\tsconfig.build.json' @'

{
  "extends": "../../tsconfig.base.json",
