export function generateId(prefix = 'id'): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}
'@
Write-Utf8File 'packages\shared\src\index.ts' @'

export * from './types';
export * from './ids';
export * from './math';
export * from './time';
'@
Write-Utf8File 'packages\shared\src\math.ts' @'

export function safeAdd(a: number, b: number): number {
  return Number.isFinite(a) && Number.isFinite(b) ? a + b : 0;
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function toBps(percent: number): number {
  return Math.round(percent * 100);
}

export function fromBps(bps: number): number {
  return bps / 100;
}
'@
Write-Utf8File 'packages\shared\src\time.ts' @'

export function nowIso(): string {
  return new Date().toISOString();
}

export function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function ageMs(timestamp: number): number {
  return Date.now() - timestamp;
}
'@
Write-Utf8File 'packages\shared\src\types.ts' @'

export type OrderId = string;
export type PositionId = string;
export type TokenMint = string;
export type TxSignature = string;
