Write-Utf8File 'packages\solana\src\connection.ts' @'

import {
  Connection,
  PublicKey,
  Commitment,
  TransactionSignature,
  BlockhashWithExpiryBlockHeight,
} from '@solana/web3.js';

const MAX_FAILURES_BEFORE_SWITCH = 3;
const LAMPORTS_PER_SOL = 1_000_000_000;

export class SolanaConnection {
  private primaryUrl: string;
  private backupUrl: string | undefined;
  private connection: Connection;
  private usingBackup = false;
  private consecutiveFailures = 0;

  constructor(rpcUrl: string, backupRpcUrl?: string) {
    this.primaryUrl = rpcUrl;
    this.backupUrl = backupRpcUrl;
    this.connection = new Connection(rpcUrl, 'confirmed');
  }

  getConnection(): Connection {
    return this.connection;
  }

  switchToBackup(): void {
    if (!this.backupUrl) {
      throw new Error('No backup RPC URL configured');
    }
    this.connection = new Connection(this.backupUrl, 'confirmed');
    this.usingBackup = true;
    this.consecutiveFailures = 0;
  }

  isUsingBackup(): boolean {
    return this.usingBackup;
  }

  private async withAutoSwitch<T>(fn: () => Promise<T>): Promise<T> {
    try {
      const result = await fn();
      this.consecutiveFailures = 0;
      return result;
    } catch (error) {
      this.consecutiveFailures++;
      if (this.consecutiveFailures >= MAX_FAILURES_BEFORE_SWITCH && this.backupUrl && !this.usingBackup) {
        this.switchToBackup();
        return fn();
      }
      throw error;
    }
  }

  async getBalance(pubkey: string): Promise<number> {
    return this.withAutoSwitch(async () => {
      const balance = await this.connection.getBalance(new PublicKey(pubkey));
      return balance / LAMPORTS_PER_SOL;
    });
  }

  async getTokenBalances(pubkey: string): Promise<Map<string, number>> {
    return this.withAutoSwitch(async () => {
      const owner = new PublicKey(pubkey);
      const tokenAccounts = await this.connection.getParsedTokenAccountsByOwner(owner, {
        programId: new PublicKey('TokenkegQfeN4jV6Mtibt44sXBk6czguMmhN5VL8DvV6'),
      });

      const balances = new Map<string, number>();
      for (const account of tokenAccounts.value) {
        const parsed = account.account.data.parsed;
        const mint: string = parsed.info.mint;
        const amount: number = parsed.info.tokenAmount.uiAmount ?? 0;
        if (amount > 0) {
          balances.set(mint, amount);
        }
      }
      return balances;
    });
  }

  async getLatestBlockhash(): Promise<BlockhashWithExpiryBlockHeight> {
    return this.withAutoSwitch(() => this.connection.getLatestBlockhash());
  }

  async confirmTransaction(
    signature: TransactionSignature,
    commitment: Commitment = 'confirmed',
  ): Promise<void> {
    const { blockhash, lastValidBlockHeight } = await this.getLatestBlockhash();
    await this.connection.confirmTransaction(
      { signature, blockhash, lastValidBlockHeight },
      commitment,
    );
  }
}
