import {
  Connection,
  PublicKey,
  Logs,
} from '@solana/web3.js';
import { TokenDiscoveryProvider } from './provider';
import {
  TokenCallback,
  TokenDiscoveryEvent,
  LiquidityCallback,
} from './types';

const RAYDIUM_AMM_V4 = new PublicKey(
  '675kPX9MHTjS2zt1qfr1NYHuzeLXfQM9H24wFSUt1Mp8',
);

const RAYDIUM_CPMM = new PublicKey(
  'CPMMoo8L3F4NbTegBCKVNunggL7H1ZpdTHKxQB5qKP1C',
);

const SOL_MINT = 'So11111111111111111111111111111111111111112';
const WSOL_MINT = SOL_MINT;

const MAX_SEEN = 5000;

export class RaydiumLpProvider implements TokenDiscoveryProvider {
  name = 'raydium-lp';

  private readonly connection: Connection;
  private readonly wsConnection: Connection;
  private readonly tokenCallbacks: TokenCallback[] = [];
  private readonly liquidityCallbacks: LiquidityCallback[] = [];
  private subscriptionIds: number[] = [];
  private readonly seenSignatures = new Set<string>();
  private readonly seenMints = new Set<string>();

  constructor(rpcUrl: string) {
    if (!rpcUrl || !rpcUrl.trim()) {
      throw new Error('Solana RPC URL is required');
    }

    this.connection = new Connection(rpcUrl, {
      commitment: 'confirmed',
      disableRetryOnRateLimit: true,
    });

    const wsUrl = rpcUrl
      .replace(/^https:/, 'wss:')
      .replace(/^http:/, 'ws:');

    this.wsConnection = new Connection(rpcUrl, {
      commitment: 'confirmed',
      wsEndpoint: wsUrl,
    });
  }

  async start(): Promise<void> {
    if (this.subscriptionIds.length > 0) return;

    console.log(`[${this.name}] subscribing to Raydium AMM V4 + CPMM`);

    this.subscribeToProgram(RAYDIUM_AMM_V4, 'raydium-amm-v4', [
      'initialize2',
      'Initialize2',
    ]);

    this.subscribeToProgram(RAYDIUM_CPMM, 'raydium-cpmm', [
      'initialize',
      'Initialize',
    ]);
  }

  async stop(): Promise<void> {
    for (const id of this.subscriptionIds) {
      try {
        await this.wsConnection.removeOnLogsListener(id);
      } catch {}
    }
    this.subscriptionIds = [];
    console.log(`[${this.name}] stopped`);
  }

  onToken(callback: TokenCallback): void {
    this.tokenCallbacks.push(callback);
  }

  onLiquidityChange(callback: LiquidityCallback): void {
    this.liquidityCallbacks.push(callback);
  }

  private subscribeToProgram(
    programId: PublicKey,
    label: string,
    initKeywords: string[],
  ): void {
    try {
      const id = this.wsConnection.onLogs(
        programId,
        async (logs: Logs) => {
          if (logs.err) return;

          const hasInit = logs.logs.some((line) =>
            initKeywords.some((kw) => line.includes(kw)),
          );
          if (!hasInit) return;

          if (this.seenSignatures.has(logs.signature)) return;
          this.seenSignatures.add(logs.signature);
          this.trimSeen();

          const startTime = Date.now();

          console.log(
            `[${this.name}] LP_CREATED program=${label} sig=${logs.signature}`,
          );

          try {
            await this.processLpCreation(logs.signature, label);
            console.log(
              `[${this.name}] processed in ${Date.now() - startTime}ms`,
            );
          } catch (err) {
            console.warn(
              `[${this.name}] processing failed ${logs.signature}:`,
              err instanceof Error ? err.message : String(err),
            );
          }
        },
        'confirmed',
      );

      this.subscriptionIds.push(id);
      console.log(`[${this.name}] subscribed to ${label} (id=${id})`);
    } catch (err) {
      console.warn(
        `[${this.name}] WebSocket subscription failed for ${label}: ` +
        `${err instanceof Error ? err.message : String(err)}`,
      );
    }
  }

  private async processLpCreation(
    signature: string,
    source: string,
  ): Promise<void> {
    const tx = await this.connection.getParsedTransaction(signature, {
      maxSupportedTransactionVersion: 0,
    });

    if (!tx?.meta || tx.meta.err) return;

    const tokenMint = this.extractTokenMint(tx);
    if (!tokenMint) return;
    if (this.seenMints.has(tokenMint)) return;
    this.seenMints.add(tokenMint);

    const poolAddress = this.extractPoolAddress(tx);
    const liquidity = this.extractLiquidity(tx);
    const creator = tx.transaction.message.accountKeys[0]?.pubkey?.toBase58() ?? 'unknown';
    const blockTime = tx.blockTime ?? Math.floor(Date.now() / 1000);

    const event: TokenDiscoveryEvent = {
      tokenMint,
      creator,
      createdAt: new Date(blockTime * 1000),
      poolAddress,
      quoteToken: SOL_MINT,
      initialLiquidity: liquidity,
      decimals: 9,
      name: null,
      symbol: null,
      supply: 0,
      mintAuthority: null,
      freezeAuthority: null,
      metadataUri: null,
      txSignature: signature,
      source: `${this.name}:${source}`,
    };

    console.log(
      `[${this.name}] NEW_LP mint=${tokenMint} pool=${poolAddress} ` +
      `liq=${liquidity?.toFixed(2) ?? '?'} SOL`,
    );

    for (const cb of this.tokenCallbacks) {
      try {
        await cb(event);
      } catch (err) {
        console.warn(
          `[${this.name}] callback error:`,
          err instanceof Error ? err.message : String(err),
        );
      }
    }
  }

  private extractTokenMint(
    tx: { transaction: { message: { accountKeys: Array<{ pubkey: PublicKey }> } }; meta: any },
  ): string | null {
    const accounts = tx.transaction.message.accountKeys;
    for (const acc of accounts) {
      const key = acc.pubkey.toBase58();
      if (key === SOL_MINT || key === WSOL_MINT) continue;
      if (key === RAYDIUM_AMM_V4.toBase58()) continue;
      if (key === RAYDIUM_CPMM.toBase58()) continue;
      if (this.looksLikeMint(key, tx)) return key;
    }
    return null;
  }

  private looksLikeMint(
    key: string,
    tx: { meta: any },
  ): boolean {
    const preBalances = tx.meta?.preTokenBalances ?? [];
    const postBalances = tx.meta?.postTokenBalances ?? [];
    for (const bal of [...preBalances, ...postBalances]) {
      if (bal.mint === key) return true;
    }
    return false;
  }

  private extractPoolAddress(
    tx: { transaction: { message: { accountKeys: Array<{ pubkey: PublicKey }> } }; meta: any },
  ): string | null {
    const accounts = tx.transaction.message.accountKeys;
    if (accounts.length >= 5) {
      return accounts[4]?.pubkey?.toBase58() ?? null;
    }
    return null;
  }

  private extractLiquidity(
    tx: { meta: any },
  ): number | null {
    if (!tx.meta?.preBalances || !tx.meta?.postBalances) return null;

    let maxDrop = 0;
    for (let i = 0; i < tx.meta.preBalances.length; i++) {
      const pre = tx.meta.preBalances[i];
      const post = tx.meta.postBalances[i];
      const drop = (pre - post) / 1e9;
      if (drop > maxDrop) maxDrop = drop;
    }

    return maxDrop > 0.001 ? maxDrop : null;
  }

  private trimSeen(): void {
    if (this.seenSignatures.size > MAX_SEEN) {
      const entries = Array.from(this.seenSignatures);
      this.seenSignatures.clear();
      for (const s of entries.slice(-MAX_SEEN / 2)) {
        this.seenSignatures.add(s);
      }
    }
    if (this.seenMints.size > MAX_SEEN) {
      const entries = Array.from(this.seenMints);
      this.seenMints.clear();
      for (const m of entries.slice(-MAX_SEEN / 2)) {
        this.seenMints.add(m);
      }
    }
  }
}
