import { vi } from 'vitest';

// Lightweight compatibility layer for tests that still use the `jest` global.
// Maps a small surface of `jest` to `vitest`'s `vi` so older tests run under Vitest.
const jestShim = {
  fn: vi.fn,
  mock: vi.mock,
  clearAllMocks: vi.clearAllMocks,
  spyOn: vi.spyOn,
};

(globalThis as any).jest = jestShim;
(globalThis as any).jestMock = jestShim;

export {};
